messageText:
添加 `InitLogFile` 函数，它需要 JNIEnv 来获取应用私有目录。我们把它放在 `InitJavaFilePicker` 之前或之后调用。其实可以用同样的方式获取 context。我加一个 `InitLogFile` 函数：

```cpp
void InitLogFile(JNIEnv* env) {
    // 获取 context.getFilesDir()
    jclass contextClass = env->FindClass("android/content/Context");
    jclass unityPlayerCls = env->FindClass("com/unity3d/player/UnityPlayer");
    jfieldID activityField = env->GetStaticFieldID(unityPlayerCls, "currentActivity", "Landroid/app/Activity;");
    jobject activity = env->GetStaticObjectField(unityPlayerCls, activityField);
    jmethodID getFilesDir = env->GetMethodID(env->GetObjectClass(activity), "getFilesDir", "()Ljava/io/File;");
    jobject filesDir = env->CallObjectMethod(activity, getFilesDir);
    jclass fileClass = env->FindClass("java/io/File");
    jmethodID getAbsolutePath = env->GetMethodID(fileClass, "getAbsolutePath", "()Ljava/lang/String;");
    jstring pathStr = (jstring)env->CallObjectMethod(filesDir, getAbsolutePath);

    const char* path = env->GetStringUTFChars(pathStr, nullptr);
    g_logPath = path ? path : "/data/data/com.DefaultCompany.Myproject/files/adofai_mod.log";
    env->ReleaseStringUTFChars(pathStr, path);

    g_logFile.open(g_logPath, std::ios::out | std::ios::app);
    if (g_logFile.is_open()) {
        LOGD("Log file initialized: %s", g_logPath.c_str());
    }

    // 清理局部引用
    env->DeleteLocalRef(activity);
    env->DeleteLocalRef(unityPlayerCls);
    env->DeleteLocalRef(filesDir);
    env->DeleteLocalRef(fileClass);
    env->DeleteLocalRef(pathStr);
}
```

但注意：`UnityPlayer` 可能已经获取过 activity，我们可以复用。或者在 `JNI_OnLoad` 时就用一次 JNI 调用 init log。我选择在 `JNI_OnLoad` 的 `AddOnLoadedEvent` 里调用 `InitLogFile`，这样 IL2CPP 还没加载，但 JNIEnv 可用。

修改 `JNI_OnLoad` 部分的代码。
</think>

