import android.app.Activity;
import android.content.ContentResolver;
import android.content.Intent;
import android.database.Cursor;
import android.net.Uri;
import android.provider.DocumentsContract;
import android.provider.MediaStore;

public class FilePicker {
    private static Activity unityActivity;
    private static long nativeCallbackPtr = 0;

    // 初始化：传入 Unity Activity 和 C++ 回调指针
    public static void initialize(Activity activity, long callbackPtr) {
        unityActivity = activity;
        nativeCallbackPtr = callbackPtr;
    }

    // 显示文件选择器（支持 .adofai, .zip 等）
    public static void show() {
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        intent.setType("*/*");
        String[] mimeTypes = {
            "application/octet-stream",
            "application/json",
            "text/plain",
            "application/zip",
            "application/x-zip-compressed",
            "application/x-adofai"
        };
        intent.putExtra(Intent.EXTRA_MIME_TYPES, mimeTypes);
        // 使用 requestCode 54321
        unityActivity.startActivityForResult(intent, 54321);
    }

    // 处理结果（需在 UnityPlayerActivity.onActivityResult 中调用）
    public static void onActivityResult(int requestCode, int resultCode, Intent data) {
        if (requestCode != 54321) return;

        String path = null;
        if (resultCode == Activity.RESULT_OK && data != null) {
            Uri uri = data.getData();
            if (uri != null) {
                path = getRealPath(uri);
            }
        }

        // 回调到 C++（nativeOnFileSelected 已在 Main.cpp 实现）
        nativeOnFileSelected(nativeCallbackPtr, path);
    }

    private static String getRealPath(Uri uri) {
        // 调试：输出 uri 信息
        android.util.Log.d("FilePicker", "getRealPath: uri=" + uri.toString() + ", scheme=" + uri.getScheme());

        // 如果是 file:// URI，直接返回路径
        if ("file".equals(uri.getScheme())) {
            String path = uri.getPath();
            android.util.Log.d("FilePicker", "file scheme, path=" + path);
            return path;
        }

        // content:// URI：通过 ContentResolver 查询 _data 列
        ContentResolver resolver = unityActivity.getContentResolver();
        String[] projection = { "_data" };  // 使用 _data 列名
        try (Cursor cursor = resolver.query(uri, projection, null, null, null)) {
            if (cursor != null) {
                android.util.Log.d("FilePicker", "cursor count=" + cursor.getCount());
                if (cursor.moveToFirst()) {
                    int columnIndex = cursor.getColumnIndex("_data");
                    if (columnIndex != -1) {
                        String path = cursor.getString(columnIndex);
                        android.util.Log.d("FilePicker", "query _data returned: " + path);
                        return path;
                    } else {
                        android.util.Log.w("FilePicker", "_data column not found");
                    }
                }
                cursor.close();
            } else {
                android.util.Log.w("FilePicker", "cursor is null");
            }
        } catch (Exception e) {
            android.util.Log.e("FilePicker", "Exception querying uri", e);
        }

        // 回退：尝试用 uri.getPath()
        String path = uri.getPath();
        if (path != null && !path.isEmpty()) {
            android.util.Log.d("FilePicker", "fallback to uri.getPath(): " + path);
            return path;
        }

        // 最后回退：返回 uri.toString()
        String fallback = uri.toString();
        android.util.Log.d("FilePicker", "fallback to uri.toString(): " + fallback);
        return fallback;
    }

    // 原生回调函数声明（由 C++ 提供实现）
    private static native void nativeOnFileSelected(long callbackPtr, String path);
}","new_string":"package com.mod.filepicker;

